<?php $reviewPage=max(1,min(100000,(int)($_GET['review_page']??1)));$reviews=$a->reviews->listing((int)$item['id'],$reviewPage);$own=$me?$a->db->one('SELECT * FROM cy_reviews WHERE content_id=? AND user_id=?',[(int)$item['id'],(int)$me['id']]):null; ?>
<section class="panel glass product-reviews section" id="product-reviews"><div class="section-heading"><div><span class="eyebrow">EXPERIENCED, NOT INVENTED</span><h2><?= t('Verified purchase reviews') ?></h2></div><div class="rating-summary"><strong><?= $reviews['average']===null?'--':e($reviews['average']) ?></strong><small>/ 5 &middot; <?= (int)$reviews['total'] ?> <?= t('reviews') ?></small></div></div>
<?php if($me && $a->reviews->eligible((int)$me['id'],(int)$item['id'])): ?><details class="review-compose"><summary><?= t($own?'Edit your review':'Share your experience') ?><?php if($own): ?> <span class="pill"><?= t($own['status']) ?></span><?php endif ?></summary><?= form_start('review_save') . hidden('content_id',$item['id']) ?><?php select_field('rating','Your rating',[5=>tr('5 - Excellent'),4=>tr('4 - Good'),3=>tr('3 - Fair'),2=>tr('2 - Disappointing'),1=>tr('1 - Poor')],$own['rating']??5);field('body','Your experience',$own['body']??'','textarea',['required'=>'required','maxlength'=>'2000']);button('Submit review','','star'); ?><p class="hint"><?= t('One review per account and product. Edits may require moderation. Refunded purchases do not count toward ratings.') ?></p></form></details><?php endif ?>
<div class="review-list"><?php foreach($reviews['items'] as $review): ?><article class="review-item"><header><?= avatar($review,'small') ?><div class="grow"><strong><?= e($review['display_name']) ?></strong><div class="row"><span class="rating-stars" aria-label="<?= (int)$review['rating'] ?> / 5"><?= str_repeat('&#9733;',(int)$review['rating']).str_repeat('&#9734;',5-(int)$review['rating']) ?></span><span class="pill soft"><?= icon('check') ?><?= t('Verified purchase') ?></span></div></div><time><?= dt((int)$review['updated_at']) ?></time></header><p><?= nl2br(e($review['body'])) ?></p></article><?php endforeach ?><?php if(!$reviews['items']){empty_state('No verified reviews yet.','star');} ?></div>
<?php partial('pagination',['route'=>'article','pagination'=>$reviews,'page_key'=>'review_page','anchor'=>'product-reviews']); ?></section>
